import SwiftUI

struct AlertsView:View{
    @AppStorage("alertFinal")private var finalLock=true;@AppStorage("alertLineups")private var lineups=true;@AppStorage("alertMarket")private var market=true;@AppStorage("alertResults")private var results=true;@AppStorage("alertNoLongerQualifies")private var disqualified=true
    var body:some View{NavigationStack{ZStack{AppTheme.background.ignoresSafeArea();ScrollView{VStack(spacing:16){VStack(alignment:.leading,spacing:7){Text("Signal, not noise").font(.title2.bold());Text("Choose the model events worth interrupting your day. Push delivery will activate when the hosted backend is connected.").font(.subheadline).foregroundStyle(AppTheme.muted)}.frame(maxWidth:.infinity,alignment:.leading).panel();VStack(spacing:0){alert("Both lineups confirmed","person.3.fill",$lineups);Divider();alert("Final prediction locked","lock.fill",$finalLock);Divider();alert("Meaningful market movement","chart.line.uptrend.xyaxis",$market);Divider();alert("Pick no longer qualifies","exclamationmark.triangle.fill",$disqualified);Divider();alert("Result automatically graded","checkmark.seal.fill",$results)}.panel();VStack(alignment:.leading,spacing:9){Label("No sportsbook alerts",systemImage:"hand.raised.fill").foregroundStyle(AppTheme.green);Text("Jingleez never sends bet-slip links, accepts wagers, holds funds or connects to sportsbook accounts.").font(.caption).foregroundStyle(AppTheme.muted)}.frame(maxWidth:.infinity,alignment:.leading).panel()}.padding(16)}}.navigationTitle("Alerts")}}
    private func alert(_ title:String,_ icon:String,_ binding:Binding<Bool>)->some View{Toggle(isOn:binding){Label(title,systemImage:icon).font(.subheadline)}.tint(AppTheme.gold).padding(.vertical,12)}
}
